import javax.swing.*;import java.awt.*;import java.awt.event.*;
public class ConverterFrameListener extends JFrame implements ActionListener {JTextField amount=new JTextField(10);JComboBox<String> target=new JComboBox<>(new String[]{"USD","EUR"});JLabel result=new JLabel(" ");ConverterFrameListener(){setLayout(new FlowLayout());JButton b=new JButton("Convert");add(amount);add(target);add(b);add(result);b.addActionListener(this);amount.addActionListener(this);addWindowListener(new WindowAdapter(){public void windowClosing(WindowEvent e){dispose();}});pack();}public void actionPerformed(ActionEvent e){convert();}void convert(){try{double v=Double.parseDouble(amount.getText().trim());if(!Double.isFinite(v)||v<0)throw new NumberFormatException();result.setText(String.format("%.2f",v*(target.getSelectedItem().equals("USD")?.012:.011)));JOptionPane.showMessageDialog(this,result.getText()+" "+target.getSelectedItem(),"Conversion result",JOptionPane.INFORMATION_MESSAGE);}catch(Exception e){result.setText("Invalid amount");JOptionPane.showMessageDialog(this,"Invalid amount","Input error",JOptionPane.ERROR_MESSAGE);}}public static void main(String[]x){SwingUtilities.invokeLater(()->new ConverterFrameListener().setVisible(true));}}
